        print(json.dumps(category_dict_list))

    def report_job(self, job):
        category = '{:s}-{:s}'.format(job.tool, job.type)
        self._report_job(job.timestamp, '{:s}-{:s}.STATUS'.format(job.tool, job.type), '{:d} ({:s})'.format(job.status, 'SUCCESS' if job.status else 'FAILURE'))
