class Node(object):
    def __eq__(self, other):
        return (
            self.__class__ == other.__class__ and
            self.__dict__ == other.__dict__
        )

    def __ne__(self, other):
        return not self == other

# The following should probably be decorators

def children(self):
    for attr, value in sorted(self.__dict__.items()):
        if isinstance(value, Node):
            yield value

def transform(self, f, already_seen=None):
    if already_seen is None:
        already_seen = set()
    if id(self) in already_seen:
        return self
    already_seen.add(id(self))
    new_attrs = {}
    for attr, value in self.__dict__.items():
        if isinstance(value, Node):
            value = value.transform(f, already_seen)
        if value is not None:
            new_attrs[attr] = value
    new_self = f(self, new_attrs)
    return new_self

Node.children = children
Node.transform = transform

class AnonymousPlaceholder(Node):
    pass

class Application(Node):
    def __init__(self, function, argument, placeholder=None):
        self.function = function
        self.argument = argument
        self.placeholder = placeholder

