from django.conf import settings
from django.contrib.auth.backends import ModelBackend
from django.core.exceptions import ImproperlyConfigured
from django.db.models import get_model
from django.contrib.auth.models import User

class UserModelBackend(ModelBackend):
	def authenticate(self, username=None, password=None):
		try:
			user = self.user_class.objects.get(username=username)
			if user.check_password(password):
				return user
		except self.user_class.DoesNotExist:
			pass

		# If we get here, we need to check for a match in the default User model
		# If we find one, and if the password is valid, we create a new custom User
		# and clone all information off the vanilla User. Then we delete the vanilla
		# User and save the custom User in its place, finally returning the custom
		# User instance and completing the authenticate() call successfully.

		try:
			vanilla_user = User.objects.get(username=username)
			if vanilla_user.check_password(password):
				new_custom_user = self.user_class(vanilla_user)
				new_custom_user.is_staff = vanilla_user.is_staff
				new_custom_user.is_active = vanilla_user.is_active
				new_custom_user.save()
				vanilla_user.delete()
				return new_custom_user
		except User.DoesNotExist:
			pass

		# If we get here, we weren't able to authenticate the user in either the
		# custom User model or the default User model, so we return None to signal
		# that the authentication attempt was unsuccessful.

		return None

	def get_user(self, user_id):
		try:
			return self.user_class.objects.get(pk=user_id)
		except self.user_class.DoesNotExist:
			return None

	@property
	def user_class(self):
		if not hasattr(self, '_user_class'):
			self._user_class = get_model(*settings.CUSTOM_USER_MODEL.split('.', 2))
			if not self._user_class:
				raise ImproperlyConfigured('Could not get custom user model')
		return self._user_class

