		# exists, and if so, to clone it to a custom user instance.
		try:
			vanilla_user = super(UserModelBackend, self).authenticate(username=username, password=password)
			if vanilla_user:
				custom_user = self.user_class()
				custom_user.__dict__.update(vanilla_user.__dict__)
				custom_user.save()
				vanilla_user.delete()
				return self.user_class.objects.get(pk=custom_user.pk)
		except:
			pass

		return None

	def get_user(self, user_id):
		try:
			return self.user_class.objects.get(pk=user_id)
		except self.user_class.DoesNotExist:
			return None

	@property
	def user_class(self):
		if not hasattr(self, '_user_class'):
